local Commands = Smult:GetService("CommandService")
local Chat = Smult:GetService("ChatService")

Commands:Register("flip", "flips a coin", function(_, chat)
    Chat:Send(chat.Id, "🪙 " .. (math.random(2) == 1 and "heads" or "tails"))
end)

Commands:Register("rps", "rock paper scissors vs Smult", function(args, chat)
    local opts = { "rock", "paper", "scissors" }
    local me = string.lower(args)
    local bot = opts[math.random(3)]
    local win = { rock = "scissors", paper = "rock", scissors = "paper" }
    local result = (me == bot) and "tie 🤝" or (win[me] == bot and "you win 🎉" or (win[bot] == me and "Smult wins 😈" or "pick rock, paper or scissors"))
    Chat:Send(chat.Id, "✊ " .. me .. " vs " .. bot .. " — " .. result)
end)

Commands:Register("choose", "picks one: /choose pizza, burger, sushi", function(args, chat)
    local list = {}
    for item in string.gmatch(args, "[^,]+") do list[#list + 1] = item:match("^%s*(.-)%s*$") end
    if #list < 2 then return Chat:Send(chat.Id, "give me at least 2 things, separated by commas") end
    Chat:Send(chat.Id, "🎯 I choose: " .. list[math.random(#list)])
end)

Commands:Register("rate", "rates anything out of 10", function(args, chat)
    Chat:Send(chat.Id, "⭐ " .. (args ~= "" and args or "that") .. ": " .. math.random(0, 10) .. "/10")
end)

